import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

interface ReportDatePickerProps {
  onChange?: (date: Date) => void;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

function isSameDay(a: Date | null, b: Date): boolean {
  if (!a) return false;
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

const today = startOfDay(new Date());
const yesterday = addDays(today, -1);
const weekAgo = addDays(today, -7);

const quickOptions = [
  { label: 'Сегодня', date: today },
  { label: 'Вчера', date: yesterday },
  { label: 'Неделя назад', date: weekAgo },
];

export default function ReportDatePicker({ onChange }: ReportDatePickerProps) {
  const [selectedDate, setSelectedDate] = useState<Date | null>(today);

  const handleChange = (date: Date | null) => {
    setSelectedDate(date);
    if (date) {
      onChange?.(date);
    }
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-r-sm)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', gap: 'var(--jx-r-sm)', flexWrap: 'wrap' }}>
        {quickOptions.map((option) => (
          <JxChip
            key={option.label}
            active={isSameDay(selectedDate, option.date)}
            onClick={() => handleChange(option.date)}
          >
            {option.label}
          </JxChip>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={selectedDate} onValueChange={handleChange} />
    </div>
  );
}

